import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Reduce over dim=1 for a 3D tensor of shape (B, D1, D2)
// Output shape (B, D2)
// Threads are laid out along D2 dimension so that consecutive threads
// access consecutive memory locations (coalesced) for a fixed i.
// Reduce over dim=1 for a 3D tensor of shape (B, D1, D2)
// Output shape (B, D2)
// Each thread handles COLS_PER_THREAD interleaved columns (stride = blockDim.x)
// so that memory accesses remain fully coalesced across the warp while
// exposing more independent (non-dependent) loads per thread to hide
// global memory latency (memory-level parallelism).
#define COLS_PER_THREAD 4
__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int B, int D1, int D2) {
    int b = blockIdx.x;
    if (b >= B) return;
    int chunk = blockDim.x * COLS_PER_THREAD;
    int col_start = blockIdx.y * chunk + threadIdx.x;
    int cols[COLS_PER_THREAD];
    float max_val[COLS_PER_THREAD];
    #pragma unroll
    for (int k = 0; k < COLS_PER_THREAD; ++k) {
        cols[k] = col_start + k * blockDim.x;
        max_val[k] = -FLT_MAX;
    }
    const float* base = x + (size_t)b * D1 * D2;
    size_t strideD2 = (size_t)D2;
    for (int i = 0; i < D1; ++i) {
        const float* row = base + (size_t)i * strideD2;
        #pragma unroll
        for (int k = 0; k < COLS_PER_THREAD; ++k) {
            if (cols[k] < D2) {
                float v = row[cols[k]];
                max_val[k] = fmaxf(max_val[k], v);
            }
        }
    }
    #pragma unroll
    for (int k = 0; k < COLS_PER_THREAD; ++k) {
        if (cols[k] < D2) {
            out[(size_t)b * D2 + cols[k]] = max_val[k];
        }
    }
}
// Reduce over dim=0 for a 3D tensor of shape (D0, D1, D2)
// Output shape (D1, D2)
__global__ void max_reduce_dim0_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int D0, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = D1 * D2;
    if (idx >= total) return;
    const float* base = x + idx;
    float max_val = -FLT_MAX;
    size_t stride = (size_t)D1 * D2;

    for (int i = 0; i < D0; ++i) {
        float val = base[(size_t)i * stride];
        max_val = val > max_val ? val : max_val;
    }

    out[idx] = max_val;
}

// Reduce over dim=2 (last dim) for a 3D tensor of shape (D0, D1, D2)
// Output shape (D0, D1)
__global__ void max_reduce_dim2_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int D0, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = D0 * D1;
    if (idx >= total) return;

    const float* base = x + (size_t)idx * D2;
    float max_val = -FLT_MAX;

    for (int i = 0; i < D2; ++i) {
        float val = base[i];
        max_val = val > max_val ? val : max_val;
    }

    out[idx] = max_val;
}

torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "Input must be a 3D tensor");
    x = x.contiguous();

    int D0 = x.size(0);
    int D1 = x.size(1);
    int D2 = x.size(2);

    torch::Tensor out;

    if (dim == 1) {
        out = torch::empty({D0, D2}, x.options());
        int threads = 256;
        int chunk = threads * COLS_PER_THREAD;
        dim3 block(threads);
        dim3 grid(D0, (D2 + chunk - 1) / chunk);
        max_reduce_dim1_kernel<<<grid, block>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), D0, D1, D2);
    } else if (dim == 0) {
        out = torch::empty({D1, D2}, x.options());
        int total = D1 * D2;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        max_reduce_dim0_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), D0, D1, D2);
    } else if (dim == 2) {
        out = torch::empty({D0, D1}, x.options());
        int total = D0 * D1;
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        max_reduce_dim2_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), D0, D1, D2);
    } else {
        TORCH_CHECK(false, "Unsupported dim");
    }

    return out;
}
"""

cpp_source = r"""
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim);
"""

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return max_reduce_module.max_reduce_cuda(x, self.dim)


batch_size = 128
dim1 = 4096
dim2 = 4095


def get_inputs():
    x = torch.rand(batch_size, dim1, dim2).cuda()
    return [x]


def get_init_inputs():
    return [1]

